const plannerRes = $('Planner Agent').item.json;

let selected = "default";
let requiresRag = false;
let predictedIntents = [];

try {
  const text = plannerRes.text;
  const cleanText = text.replace(/```json/gi, "").replace(/```/gi, "").trim();
  const parsed = JSON.parse(cleanText);
  selected = parsed.selected_agent || "default";
  requiresRag = (parsed.requires_rag === true || parsed.requires_rag === "true");
  predictedIntents = parsed.predicted_intents || [];
} catch (e) {
  selected = "default";
  requiresRag = false;
  predictedIntents = [];
}

return {
  selected_agent: selected,
  requires_rag: requiresRag,
  predicted_intents: predictedIntents
};

const retrievalData = $('Call Python Retrieval API').first().json;
const results = (retrievalData.results || []).filter(r => r.distance === undefined || r.distance < 1.6);

const contextTexts = [];
const citations = [];
let retrievalFailed = false;

if (results.length === 0) {
  retrievalFailed = true;
} else {
  results.forEach((chunk, index) => {
    const meta = chunk.metadata || {};
    const physPage = meta.physical_page;
    const pdfPage = meta.pdf_page_number || (meta.pdf_page_index !== undefined ? meta.pdf_page_index + 1 : undefined);
    const pageStr = (physPage !== undefined && physPage !== -1) ? `Trang ${physPage}` : (pdfPage !== undefined ? `Trang PDF ${pdfPage}` : 'Trang chưa rõ');
    const lessonName = meta.lesson_name || 'Chưa rõ';
    const fileName = meta.file_name || 'SGK Toán 3';
    const volume = meta.volume || '1';
    contextTexts.push(`--- Đoạn ${index + 1}: ${fileName}, ${pageStr} ---\n${chunk.text}`);
    citations.push(`- **Tài liệu:** ${fileName} | **Bài học:** ${lessonName} | **Vị trí:** ${pageStr} (Tập ${volume})`);
  });
}

return {
  joined_context: contextTexts.join('\n\n'),
  citation_block: citations.join('\n'),
  retrieval_failed: retrievalFailed
};

let joinedContext = "";
let citationBlock = "";
let retrievalFailed = false;

const selectedAgent = $json.selected_agent;
const requiresRag = $json.requires_rag;

if (requiresRag) {
  joinedContext = $json.joined_context || "";
  citationBlock = $json.citation_block || "";
  retrievalFailed = ($json.retrieval_failed === true || $json.retrieval_failed === "true");
}

const securityNode = $('Security & Sanitization Gate').first().json.body;
const userPrompt = securityNode.prompt;
const overrides = securityNode.prompt_overrides || {};

let activePrompts = {};
try {
  activePrompts = $('Fetch Active Prompts').first().json;
} catch (e) {
  activePrompts = {};
}

const getPrompt = (agentName, defaultVal) => {
  return overrides[agentName] || activePrompts[agentName] || defaultVal;
};

let finalAgent = selectedAgent;
let finalRequires = requiresRag;
if (securityNode.agent_mode && securityNode.agent_mode !== "default" && securityNode.agent_mode !== "") {
  finalAgent = securityNode.agent_mode;
  if (securityNode.agent_mode !== "default") {
    finalRequires = true;
  }
}

// NEW RULE: if RAG is required but retrieval failed (no matching documents found in RAG),
// push to "no_intent" to present options to the user.
if (finalRequires && retrievalFailed) {
  finalAgent = "no_intent";
}

// Never block/reject using fallback text - allow external LLM intelligence for all modules
let ragGuardrailTriggered = false;

let effectiveCitationBlock = citationBlock;
if (!citationBlock || citationBlock.trim() === "" || retrievalFailed) {
  effectiveCitationBlock = "- **Nguồn tham khảo:** Kiến thức mở rộng";
}

const RAG_RULE_PREFIX = "HƯỚNG DẪN SỬ DỤNG NGỮ CẢNH & KIẾN THỨC MỞ RỘNG:\n" +
  "- Bạn ĐƯỢC PHÉP truy cập và sử dụng triệt để trí tuệ/kiến thức mở rộng của bản thân để giải đáp câu hỏi, tạo bộ bài tập hoặc giảng giải lý thuyết một cách sư phạm nhất.\n" +
  "- Nếu Ngữ cảnh SGK có thông tin, hãy ưu tiên tham khảo nội dung và độ khó từ SGK.\n" +
  "- Nếu Ngữ cảnh SGK không có hoặc không đầy đủ (hoặc retrieval không tìm thấy), hãy sử dụng kiến thức mở rộng chuyên môn để trả lời khéo léo và chính xác.\n\n" +
  "Ngữ cảnh tài liệu SGK (nếu có):\n" + joinedContext + "\n\n";

// --- Default Teacher ---
let defaultTeacherPrompt = "";
const baseDefaultTeacher = getPrompt('default_teacher', 'Bạn là một giáo viên tiểu học thân thiện, tận tụy và dịu dàng.');
if (finalRequires) {
  defaultTeacherPrompt = baseDefaultTeacher + "\n\n" + RAG_RULE_PREFIX +
    "Câu hỏi của người dùng:\n" + userPrompt +
    "\n\nYêu cầu câu trả lời:\n1. Trả lời thân thiện, giải thích từng bước logic toán học rõ ràng.\n2. Trả lời hoàn toàn bằng tiếng Việt.\n3. Cuối câu trả lời, in rõ phần trích dẫn nguồn theo đúng định dạng sau:\n\n---\n **Nguồn tham khảo:**\n" + effectiveCitationBlock;
} else {
  defaultTeacherPrompt = baseDefaultTeacher + " Hãy trò chuyện thân thiện, trả lời tự nhiên hoặc giải thích toán học đơn giản cho câu hỏi của người dùng.\n\nCâu hỏi/Lời nhắn của người dùng:\n" + userPrompt + "\n\nYêu cầu:\n1. Trả lời thân thiện, ngọt ngào bằng tiếng Việt.\n2. Cuối câu trả lời, in trích dẫn:\n\n---\n **Nguồn tham khảo:**\n- **Nguồn tham khảo:** Kiến thức mở rộng";
}

// --- Barem Reviewer ---
const baseBarem = getPrompt('barem_review', 'Bạn là một giáo viên tiểu học thân thiện, tận tụy và công tâm. Nhiệm vụ của bạn là chấm điểm và nhận xét bài làm của học sinh dựa trên Barem điểm và đáp án chuẩn được cung cấp.');
const baremPrompt = baseBarem + "\n\n" + RAG_RULE_PREFIX +
  "Câu hỏi/Yêu cầu chấm điểm (chứa Đề bài, Barem & Bài làm của học sinh):\n" + userPrompt +
  "\n\nHãy thực hiện chấm điểm và đưa ra nhận xét sư phạm chi tiết, ấm áp.\n\n---\n **Nguồn tham khảo:**\n" + effectiveCitationBlock;

// --- Theory Explainer ---
const baseTheory = getPrompt('theory_explanation', 'Bạn là một giáo viên tiểu học có tài giảng dạy trực quan, sinh động. Nhiệm vụ của bạn là giải thích các định nghĩa, khái niệm toán học lớp 3 từ sách giáo khoa một cách dễ hiểu nhất.');
const theoryPrompt = baseTheory + "\n\n" + RAG_RULE_PREFIX +
  "Câu hỏi của học sinh/phụ huynh về khái niệm lý thuyết:\n" + userPrompt +
  "\n\nGiải thích trực quan, gần gũi, dùng ví dụ thực tế cho trẻ em 8-9 tuổi.\n\n---\n **Nguồn tham khảo:**\n" + effectiveCitationBlock;

// --- Exercise Generator ---
const baseExercise = getPrompt('exercise_generator', 'Bạn là một chuyên gia biên soạn tài liệu toán tiểu học. Nhiệm vụ của bạn là tạo ra các bài tập tự luyện mới dựa trên ngữ cảnh bài học trong sách giáo khoa.');
const exercisePrompt = baseExercise + "\n\n" + RAG_RULE_PREFIX +
  "Yêu cầu tạo bài tập của người dùng:\n" + userPrompt +
  "\n\nTạo bộ bài tập 3 mức độ (Nhận biết, Vận dụng, Vận dụng cao) phù hợp với học sinh lớp 3. Tham khảo độ khó từ SGK nếu có, hoặc dùng kiến thức mở rộng để soạn bộ bài tập chất lượng.\n\n---\n **Nguồn tham khảo:**\n" + effectiveCitationBlock;

// --- Suggestive Tutor ---
const baseTutor = getPrompt('suggestive_tutor', 'Bạn là một Gia sư Toán Tiểu học có phương pháp dạy học tương tác, gợi mở (Socratic method). TUYỆT ĐỐI KHÔNG đưa ra lời giải đầy đủ hay đáp số cuối cùng ngay lập tức. Hãy dắt tay học sinh tự tìm ra đáp án.');
const tutorPrompt = baseTutor + "\n\n" + RAG_RULE_PREFIX +
  "Câu hỏi cần gợi ý của học sinh:\n" + userPrompt +
  "\n\nHướng dẫn từng bước bằng câu hỏi gợi mở, không đưa đáp số trực tiếp.\n\n---\n **Nguồn tham khảo:**\n" + effectiveCitationBlock;

// --- Direct Solver ---
const baseSolver = getPrompt('direct_solver', 'Bạn là một Trợ lý Giải Toán Tiểu học nhanh chóng và chính xác. Nhiệm vụ của bạn là đưa ra kết quả cuối cùng ngay lập tức, sau đó trình bày bài giải chi tiết theo đúng chuẩn sư phạm lớp 3.');
const solverPrompt = baseSolver + "\n\n" + RAG_RULE_PREFIX +
  "Câu hỏi/Bài toán cần giải:\n" + userPrompt +
  "\n\n[Ans] Đưa ra đáp số nhanh trước, sau đó trình bày từng bước giải chi tiết.\n\n---\n **Nguồn tham khảo:**\n" + effectiveCitationBlock;

return {
  prompt: userPrompt,
  joined_context: joinedContext,
  citation_block: effectiveCitationBlock,
  selected_agent: finalAgent,
  requires_rag: finalRequires,
  retrieval_failed: retrievalFailed,
  rag_guardrail_triggered: false,
  default_teacher_prompt: defaultTeacherPrompt,
  barem_prompt: baremPrompt,
  theory_prompt: theoryPrompt,
  exercise_prompt: exercisePrompt,
  tutor_prompt: tutorPrompt,
  solver_prompt: solverPrompt,
  predicted_intents: predictedIntents
};

let responseText = "";
const agents = ['Suggestive Tutor', 'Direct Solver', 'Default Teacher', 'Theory Explainer', 'Exercise Generator', 'Barem Reviewer'];
for (const agent of agents) {
  try {
    const nodeRes = $(agent).first().json;
    if (nodeRes && nodeRes.text) {
      responseText = nodeRes.text;
      break;
    }
  } catch (e) {}
}
const webhookBody = $('Webhook').first().json.body || {};
const conversationId = webhookBody.conversation_id || "";
return { output: responseText, conversation_id: conversationId };

const body = $('Webhook').first().json.body;

const allowlist = [
  "planner",
  "default_teacher",
  "barem_review",
  "theory_explanation",
  "exercise_generator",
  "suggestive_tutor",
  "direct_solver",
  "verifier",
  "verifier_default_teacher",
  "verifier_barem_review",
  "verifier_theory_explanation",
  "verifier_exercise_generator",
  "verifier_suggestive_tutor",
  "verifier_direct_solver",
  "document_outline"
];

let sanitizedOverrides = {};
if (body.prompt_overrides && typeof body.prompt_overrides === 'object') {
  for (const [key, value] of Object.entries(body.prompt_overrides)) {
    if (allowlist.includes(key)) {
      sanitizedOverrides[key] = value;
    }
  }
}

let tagUuidList = [];
if (body.tag_name_uuid) {
  if (Array.isArray(body.tag_name_uuid)) {
    tagUuidList = body.tag_name_uuid;
  } else if (typeof body.tag_name_uuid === 'string') {
    try {
      const parsed = JSON.parse(body.tag_name_uuid);
      if (Array.isArray(parsed)) {
        tagUuidList = parsed;
      } else {
        tagUuidList = [body.tag_name_uuid];
      }
    } catch (e) {
      tagUuidList = body.tag_name_uuid.split(',').map(s => s.trim()).filter(Boolean);
    }
  }
}

let orgIdList = [];
if (body.org_id) {
  if (Array.isArray(body.org_id)) {
    orgIdList = body.org_id;
  } else if (typeof body.org_id === 'string') {
    try {
      const parsed = JSON.parse(body.org_id);
      if (Array.isArray(parsed)) {
        orgIdList = parsed;
      } else {
        orgIdList = [body.org_id];
      }
    } catch (e) {
      orgIdList = body.org_id.split(',').map(s => s.trim()).filter(Boolean);
    }
  }
}

return {
  body: {
    prompt: body.prompt || "",
    tag_name_uuid: tagUuidList,
    org_id: orgIdList,
    agent_mode: body.agent_mode || "default",
    prompt_profile: body.prompt_profile || "default",
    prompt_version: body.prompt_version || null,
    prompt_overrides: sanitizedOverrides
  }
};

const outlineData = $('Call Python Outline API').first().json;
const outline = outlineData.outline || {};
const files = Object.keys(outline);

const webhookBody = $('Webhook').first().json.body || {};
const conversationId = webhookBody.conversation_id || "";

if (files.length === 0) {
  return {
    output: "**Mục lục tài liệu:** Hiện chưa tìm thấy danh sách bài học/chủ đề nào trong tài liệu này.",
    conversation_id: conversationId
  };
}

let lines = ["**Danh sách các chủ đề / bài học có trong tài liệu:**\n"];
files.forEach(fileName => {
  lines.push(`### ${fileName}`);
  const lessons = outline[fileName] || [];
  if (lessons.length === 0) {
    lines.push("- (Chưa có thông tin bài học)");
  } else {
    lessons.forEach(l => {
      const pageStr = (l.physical_page && l.physical_page > 0) ? `Trang ${l.physical_page}` : `Trang PDF ${l.pdf_page_number || 1}`;
      const volStr = l.volume ? ` (Tập ${l.volume})` : "";
      lines.push(`- **${l.lesson_name}** — ${pageStr}${volStr}`);
    });
  }
  lines.push("");
});

return {
  output: lines.join("\n").trim(),
  conversation_id: conversationId
};

const item = $json;
const prompt = item.prompt || "";

const VALID_MAIN_MODULES = [
  "barem_review",
  "theory_explanation",
  "exercise_generator",
  "suggestive_tutor",
  "direct_solver",
  "document_outline",
  "default"
];

const intentLabels = {
  "barem_review": "Chấm điểm và nhận xét bài làm",
  "theory_explanation": "Giải thích lý thuyết khái niệm",
  "exercise_generator": "Tạo bộ bài tập luyện tập mới",
  "suggestive_tutor": "Gia sư gợi ý từng bước tự làm",
  "direct_solver": "Giải nhanh và cho đáp án ngay",
  "document_outline": "Xem mục lục và các chủ đề sách",
  "default": "Hỏi đáp và trò chuyện thông thường"
};

let rawIntents = item.predicted_intents || [];
if (typeof rawIntents === "string") {
  try { rawIntents = JSON.parse(rawIntents); } catch(e) { rawIntents = []; }
}

// Filter to keep ONLY valid main modules (exclude "no_intent", "unclear_intent", etc.)
let cleanIntents = (Array.isArray(rawIntents) ? rawIntents : [])
  .map(i => typeof i === "object" && i !== null ? (i.intent || i.value || "") : String(i))
  .map(i => i.trim().toLowerCase())
  .filter(i => VALID_MAIN_MODULES.includes(i));

// If cleanIntents has fewer than 2 valid modules, fallback to top 3 standard modules
if (cleanIntents.length < 2) {
  cleanIntents = ["theory_explanation", "suggestive_tutor", "direct_solver"];
}

// Take 2 or 3 predicted intents max
const selectedPredicted = cleanIntents.slice(0, 3);

const formattedOptions = selectedPredicted.map((intentKey) => ({
  intent: intentKey,
  label: intentLabels[intentKey] || intentKey
}));

const webhookBody = $('Webhook').first().json.body || {};
const conversationId = webhookBody.conversation_id || "";

return {
  status: "ambiguous_intent",
  selected_agent: "no_intent",
  message: "Câu hỏi của bạn chưa rõ ý định cụ thể. Bạn vui lòng lựa chọn 1 trong các hướng hỗ trợ dưới đây:",
  predicted_intents: formattedOptions,
  original_prompt: prompt,
  conversation_id: conversationId
};
